const r = await tools.exec_command({"cmd":"python - <<'PY'
import sys, math
from pathlib import Path
import numpy as np
sys.path.insert(0,'candidates')
import classical_cv_audit as a
p=Path('input/competition/dataset')
tr,ta=a.load(p,'train'); dv,da=a.load(p,'dev')
b=a.fit_models(tr,ta); pred=a.predict(dv,b)
train_sh=[a.shingles(r['text'][:ta[r['id']]]) for r in tr]
inv={}
from collections import defaultdict
inv=defaultdict(list)
for i,ss in enumerate(train_sh):
 for x in ss: inv[x].append(i)
groups={'all':[], 'no_shared_10gram':[], 'any_shared_10gram':[], 'shared_ge_50':[], 'shared_lt_50':[]}
rows=[]
for r,prediction in zip(dv,pred):
 ss=a.shingles(r['text'][:da[r['id']]])
 counts=defaultdict(int)
 for x in ss:
  for i in inv.get(x,()):counts[i]+=1
 shared=max(counts.values(),default=0)
 val=math.exp(-abs(prediction-da[r['id']])/100)
 groups['all'].append(val)
 groups['any_shared_10gram' if shared else 'no_shared_10gram'].append(val)
 groups['shared_ge_50' if shared>=50 else 'shared_lt_50'].append(val)
 rows.append((shared,r['id'],prediction,da[r['id']],val))
for name,vals in groups.items():
 print(name,'n',len(vals),'score',100*np.mean(vals),'exact',np.mean(np.array(vals)==1) if vals else None)
print('top overlaps:')
for x in sorted(rows,reverse=True)[:25]:print(x)
